using System;
using System.Reflection;

namespace PChecker.SystematicTesting
{
    /// <summary>
    /// Stamps an assembly generated by the P compiler with the version of the runtime interface
    /// that its generated code was written against. The checker refuses to run generated code
    /// with a different version: it would bind to runtime members that no longer exist, or that
    /// now behave differently, and the checker would report misleading bugs (or miss bugs).
    /// </summary>
    /// <remarks>
    /// Generated code emits <c>[assembly: GeneratedCodeVersion(GeneratedCodeVersionAttribute.Current)]</c>,
    /// so the stamp is the version of the PCheckerCore it was compiled against. Increment
    /// <see cref="Current"/> whenever generated code (or foreign code compiled with it) must be
    /// recompiled to work with this runtime.
    /// </remarks>
    [AttributeUsage(AttributeTargets.Assembly)]
    public sealed class GeneratedCodeVersionAttribute : Attribute
    {
        /// <summary>
        /// The version of the generated code interface of this runtime. Assemblies generated
        /// before this attribute existed have no stamp, and count as version 1.
        /// </summary>
        public const int Current = 2;

        /// <summary>
        /// The version the assembly was generated for.
        /// </summary>
        public int Version { get; }

        /// <summary>
        /// Initializes a new instance of the <see cref="GeneratedCodeVersionAttribute"/> class.
        /// </summary>
        public GeneratedCodeVersionAttribute(int version)
        {
            Version = version;
        }

        /// <summary>
        /// Returns an error message if the specified assembly holds code generated by a P compiler
        /// whose generated code does not match this runtime, or null otherwise. Assemblies that were
        /// not generated by the P compiler (e.g. C# tests using the checker directly) are not stamped
        /// and are accepted.
        /// </summary>
        internal static string GetIncompatibilityError(Assembly assembly)
        {
            int version;
            var stamp = assembly.GetCustomAttribute<GeneratedCodeVersionAttribute>();
            if (stamp != null)
            {
                version = stamp.Version;
            }
            else if (IsGeneratedByP(assembly))
            {
                version = 1;
            }
            else
            {
                return null;
            }

            if (version == Current)
            {
                return null;
            }

            var age = version < Current ? "an older" : "a newer";
            var name = string.IsNullOrEmpty(assembly.Location) ? assembly.GetName().Name : assembly.Location;
            return $"'{name}' was compiled by {age} version of P, whose generated code " +
                   "is incompatible with this checker. Please re-run 'p compile' (and recompile any " +
                   "foreign code built against the P runtime), then run 'p check' again.";
        }

        /// <summary>
        /// Checks for the types that the P compiler generates into every project.
        /// </summary>
        private static bool IsGeneratedByP(Assembly assembly) =>
            assembly.GetType("PImplementation.GlobalConfig", throwOnError: false) != null ||
            assembly.GetType("PImplementation._TestRegression", throwOnError: false) != null;
    }
}
